import { useState, useEffect, FormEvent } from 'react';
import { PhoneIdentifierChallenge as ScreenProvider } from '@auth0/auth0-acul-js';
import './PhoneIdentifierChallenge.css';

const PhoneIdentifierChallenge = () => {
  const [screenProvider, setScreenProvider] = useState<ScreenProvider | null>(null);
  const [verificationCode, setVerificationCode] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [hasError, setHasError] = useState(false);

  useEffect(() => {
    try {
      const provider = new ScreenProvider();
      setScreenProvider(provider);
      console.log('PhoneIdentifierChallenge screen provider:', provider);

      if (provider.transaction?.hasErrors) {
        setHasError(true);
      }
    } catch (error) {
      console.error('Failed to initialize PhoneIdentifierChallenge screen provider:', error);
    }
  }, []);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!screenProvider) return;

    setIsLoading(true);
    setHasError(false);

    try {
      // @ts-ignore - Method might be available at runtime
      await screenProvider.submitPhoneChallenge({
        code: verificationCode,
      });
    } catch (error) {
      console.error('Verification error:', error);
      setHasError(true);
      setIsLoading(false);
    }
  };

  const handleResend = async () => {
    if (!screenProvider) return;

    try {
      // @ts-ignore - Method might be available at runtime
      await screenProvider.resendCode();
      console.log('Verification code resent');
    } catch (error) {
      console.error('Resend error:', error);
    }
  };

  const handleEdit = () => {
    if (!screenProvider) return;
    const editLink = screenProvider.screen?.links?.edit_identifier;
    if (editLink) {
      window.location.href = editLink;
    }
  };

  if (!screenProvider) {
    return (
      <div className="phone-challenge-container">
        <div style={{ textAlign: 'center', padding: '40px' }}>
          <p>Loading...</p>
        </div>
      </div>
    );
  }

  const phone = screenProvider.screen?.data?.phone || '';
  const title = screenProvider.screen?.texts?.title || 'Verify Your Phone';
  const description = screenProvider.screen?.texts?.description || 'Enter the verification code sent to your phone';
  const logoUrl = screenProvider.client?.logoUrl;
  const editLink = screenProvider.screen?.links?.edit_identifier;

  return (
    <div className="phone-challenge-container">
      <div className="logo">
        <div className="logo-box">
          {logoUrl ? (
            <img src={logoUrl} alt="Logo" style={{ width: '24px', height: '24px' }} />
          ) : (
            <span style={{ color: 'white', fontSize: '24px', fontWeight: 'bold' }}>T</span>
          )}
        </div>
        <span className="logo-text">TOYOTA</span>
      </div>

      <h1>{title}</h1>
      <p className="subtitle">{description}</p>

      {phone && (
        <div className="phone-display">
          <p className="phone-text">
            Verification code sent to: <strong>{phone}</strong>
          </p>
          {editLink && (
            <button
              type="button"
              className="edit-phone-link"
              onClick={handleEdit}
            >
              Edit Phone
            </button>
          )}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label className="form-label">
            Verification Code <span className="required-asterisk">*</span>
          </label>
          <input
            type="text"
            placeholder="Enter 6-digit code"
            value={verificationCode}
            onChange={(e) => setVerificationCode(e.target.value)}
            disabled={isLoading}
            className={hasError ? 'error' : ''}
            maxLength={6}
            autoFocus
          />
          {hasError && (
            <div className="error-message">
              Invalid verification code. Please try again.
            </div>
          )}
        </div>

        <button
          type="submit"
          className="verify-button"
          disabled={!verificationCode || isLoading}
        >
          {isLoading ? 'Verifying...' : 'Verify Phone'}
        </button>
      </form>

      <div className="resend-section">
        <p className="resend-text">Didn't receive the code?</p>
        <button
          type="button"
          className="resend-button"
          onClick={handleResend}
          disabled={isLoading}
        >
          Resend Code
        </button>
      </div>

      <div className="footer-text">
        Check your messages if you don't see the SMS. The code will expire in 10 minutes.
      </div>
    </div>
  );
};

export default PhoneIdentifierChallenge;
